"output":[[0,4,2,2,2,4,0,0],[0,0,4,2,4,0,0,0],[0,0,0,4,0,0,0,0]]})
def transform(g):
    h,w=len(g),len(g[0])
    c=next(v for row in g for v in row if v)
    out=[row[:] for row in g]
    def inb(i,j): return 0<=i<h and 0<=j<w
    for i in range(h):
        for j in range(w):
            if g[i][j]!=c: continue
            up_open = not any(inb(i-1,j+dd) and g[i-1][j+dd]==c for dd in (-1,0,1))
            dn_open = not any(inb(i+1,j+dd) and g[i+1][j+dd]==c for dd in (-1,0,1))
            if up_open:  # V: fill below between arms
                for k in range(1,h-i):
                    if inb(i+k,j-k) and inb(i+k,j+k) and g[i+k][j-k]==c and g[i+k][j+k]==c:
                        for jj in range(j-k+1,j+k):
                            if out[i+k][jj]==0: out[i+k][jj]=2
            if dn_open:  # Λ: fill above between arms
                for k in range(1,i+1):
                    if inb(i-k,j-k) and inb(i-k,j+k) and g[i-k][j-k]==c and g[i-k][j+k]==c:
                        for jj in range(j-k+1,j+k):
                            if out[i-k][jj]==0: out[i-k][jj]=2
    return out
