            up_open = not any(inb(i-1, j+dd) and grid[i-1][j+dd] == c for dd in (-1, 0, 1))
            dn_open = not any(inb(i+1, j+dd) and grid[i+1][j+dd] == c for dd in (-1, 0, 1))
            if up_open:
                for k in range(1, h-i):
                    if inb(i+k, j-k) and inb(i+k, j+k) and grid[i+k][j-k] == c and grid[i+k][j+k] == c:
                        for jj in range(j-k+1, j+k):
                            if out[i+k][jj] == 0:
